INSERT INTO risk_answer_options (id, question_id, code, text, score, sort_order) VALUES ('6f1ac520-73ec-5577-a49b-dd473b59d627', 'f181e2fc-7d47-5e84-ad88-68380479c89f', '0', 'I would want to stop and avoid further losses', 0, 0);
