INSERT INTO risk_answer_options (id, question_id, code, text, score, sort_order) VALUES ('9eb259dd-bd36-5d15-a28a-9f7c2e94a022', 'f181e2fc-7d47-5e84-ad88-68380479c89f', '2', 'I could wait while reviewing the situation', 2, 2);
