INSERT INTO risk_answer_options (id, question_id, code, text, score, sort_order) VALUES ('9e9ce70a-aede-5061-9a85-8bf1804c3a37', '59906cae-de9a-5c2a-91f9-efa6c41fcb72', '2', 'I can tolerate moderate fluctuations', 2, 2);
