INSERT INTO risk_answer_options (id, question_id, code, text, score, sort_order) VALUES ('d4e05f7e-39cc-53b7-9f52-3b49cd68be67', 'f73c8783-520b-5869-b361-426169328501', '2', 'I balance preservation and potential growth', 2, 2);
