INSERT INTO learn_articles (id, slug, title, summary, content, sort_order, active, created_at, updated_at) VALUES ('133d99f6-c25e-5ab1-9f03-9edd010a5436', 'tokenized-stocks', 'What are tokenized stocks?', 'A token and its underlying share can carry different rights.', 'A tokenized stock uses a crypto asset to represent a security or exposure to it. The structure matters: some tokens record ownership, while others provide economic exposure through a separate issuer.
INSERT INTO learn_articles (id, slug, title, summary, content, sort_order, active, created_at, updated_at) VALUES ('1991c089-720e-5073-8b47-171377f1daec', 'how-tokenization-works', 'How does tokenization work?', 'Technology records transfers; legal terms define what is transferred.', 'Tokenization represents an instrument using a blockchain record. An issuer or third party defines the connection between the token and the underlying asset.
INSERT INTO learn_articles (id, slug, title, summary, content, sort_order, active, created_at, updated_at) VALUES ('d0708484-88e1-53c0-9406-06d7ba5824fb', 'what-is-an-etf', 'What is an ETF?', 'A fund traded on an exchange, with its own strategy and risks.', 'An exchange-traded fund pools assets under a stated investment strategy. Its shares trade on an exchange. Some funds track an index; others use active strategies.
INSERT INTO learn_articles (id, slug, title, summary, content, sort_order, active, created_at, updated_at) VALUES ('2338d04a-96fe-52d8-8db6-6ad74f291f31', 'price-earnings-ratio', 'What is P/E?', 'A price-to-earnings comparison, with important limits.', 'P/E compares a share price with earnings per share. In a simple example, a price of 20 and annual earnings per share of 2 produce a P/E of 10.
INSERT INTO learn_articles (id, slug, title, summary, content, sort_order, active, created_at, updated_at) VALUES ('fc272094-4920-519d-a3f4-302b06266a94', 'market-cap', 'What is Market Cap?', 'The market value of outstanding shares, not a company’s cash balance.', 'Market capitalization is share price multiplied by the number of outstanding shares. For example, 10 million shares at 20 each give a market cap of 200 million in that currency.
INSERT INTO learn_articles (id, slug, title, summary, content, sort_order, active, created_at, updated_at) VALUES ('5f03d681-ca74-5668-b199-a7b570f0b606', 'understanding-risks', 'What are the risks?', 'Explore both underlying-market risks and token-specific risks.', 'Prices can fall, and an instrument may be difficult to sell at the expected price. A fund’s concentration, fees and strategy also matter.
INSERT INTO learn_articles (id, slug, title, summary, content, sort_order, active, created_at, updated_at) VALUES ('5e51293e-735c-543f-bc06-b4eaa8533793', 'personalization', 'How does YUDY personalize my feed?', 'Rules select examples for exploration from your profile and actions.', 'For You uses deterministic rules, not machine learning. Selected interests and regions can raise matching examples; exclusions and Not interested can lower examples with shared metadata.
INSERT INTO learn_articles (id, slug, title, summary, content, sort_order, active, created_at, updated_at) VALUES ('3959e5d4-b9dd-50f0-9b88-ee81d93c7434', 'stock-versus-token', 'Stock vs tokenized stock', 'Start with the legal claim, not the matching name or ticker.', 'A traditional share and a token referring to it are not interchangeable simply because their names match. Token rights depend on whether the issuer records ownership or a third party provides a separate claim or economic exposure.
